// === Tab: mySketch ===
let count = 50;
let particles = [];
let maxLink = 60;
let toCenter = 4;

class Particle {
  constructor(core_X, core_Y, speed, r, delta, num) {
    this.core_X = core_X;
    this.core_Y = core_Y;
    this.speed = speed;
    this.r = r;
    this.delta = delta;
    this.num = num;

    this.x = r*sin(delta) + this.core_X;
    this.y = r*cos(delta) + this.core_Y;
    this.color = color(random(100,255),
                       random(100,255),
                       random(100,255));
  }
  update() {
    if(dist(this.core_X, this.core_Y, (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))) < maxLink/2)
    {
      this.core_X += this.core_X - (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)));
      this.core_Y += this.core_Y - (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)));

      if(this.core_X < this.r*toCenter ||
       this.core_X > width-this.r*toCenter ||
       this.core_Y < this.r*toCenter ||
       this.core_Y > height-this.r*toCenter)
      {
        this.core_X = random(this.r*toCenter, width-this.r*toCenter);
        this.core_Y = random(this.r*toCenter, height-this.r*toCenter);
      }
    }

    this.delta += this.speed;
    if(this.delta >= 2*PI) this.delta -= 2*PI;
    this.x = this.r*sin(this.delta) + this.core_X;
    this.y = this.r*cos(this.delta) + this.core_Y;
  }

  draw() {
    let colorAlpha = this.color;
    colorAlpha.setAlpha(255);
    fill(colorAlpha);
    noStroke();
    ellipse(this.x, this.y, 2, 2);

    if(keyIsPressed)
    {
      var colorAlpha = color(255);
      colorAlpha.setAlpha(30);
      fill(colorAlpha);
      noStroke();
      ellipse(this.core_X, this.core_Y, this.r*2, this.r*2);
    }   
  }

  link() {
    var colorAlpha = this.color;
    colorAlpha.setAlpha(50);
    noStroke();
    fill(colorAlpha);
    for(let i = 0; i < count; i++)
    {
      if(this.num != particles[i].num &&
        dist(this.x, this.y, 
             particles[i].x, particles[i].y) < maxLink)
      {
        for(let j = 0; j < count; j++)
        {
          if(this.num != particles[j].num &&
             particles[i].num != particles[j].num &&
            dist(this.x, this.y, 
                 particles[j].x, particles[j].y) < maxLink &&
            dist(particles[i].x, particles[i].y, 
                 particles[j].x, particles[j].y) < maxLink)
          {
            triangle(this.x,this.y,
                    particles[i].x, particles[i].y,
                    particles[j].x, particles[j].y);
          }
        }
        // line(this.x, this.y, particles[i].x, particles[i].y);
      }
    }
  }
}

function setup() {
  createCanvas(400, 400);
  background(10,10,80);
  for(let i = 0; i < count; i++)
  {
    let r = random(10, 30);
    let x = random(r*toCenter, width-r*toCenter);
    let y = random(r*toCenter, height-r*toCenter);
    let speed = random(-PI/30, PI/30);
    let delta = random(0,2*PI);
    // core_X, core_Y, speed, r, delta
    particles[i] = new Particle(
      x, y, speed, r, delta, i
    )
  }
}

function draw() {
  background(10,10,80);
  for(let i = 0; i < count; i++)
  {
    particles[i].update();
    particles[i].draw();
  }
  for(let i = 0; i < count; i++)
  {
    particles[i].link();
  }
}

